// 값에 시각(t)과 작성자(by)를 함께 붙이면 병합 규칙이 생긴다
function merge(a, b) {
  if (a.t !== b.t) return a.t > b.t ? a : b;   // 시각 큰(최근) 것 승리
  return a.by > b.by ? a : b;                  // 같으면 작성자 id 로(동점 깨기 — 결정적)
}
// { v: '안녕하세요', t: 5, by: 'A' } 처럼 값에 시각·작성자를 붙임
// → 어떤 순서로 merge 해도 「가장 최근 값」이 남음(교환·결합·멱등)
// 필드마다 이렇게 = 필드 단위 LWW (대부분의 필드에 충분)
